from pydantic import BaseModel, Field

from argus.domain.claim import Claim
from argus.domain.entity import Entity


class PlannedTask(BaseModel):
    """An individual atomic task generated by the strategic planner."""

    title: str = Field(..., min_length=1, description="Concise task title")
    description: str = Field(
        ..., min_length=1, description="Detailed task requirements"
    )
    search_queries: list[str] = Field(
        default_factory=list, description="Targeted web search queries to execute"
    )
    priority: int = Field(default=5, ge=1, le=10, description="Task priority (1-10)")


class TaskPlanningPayload(BaseModel):
    """Structured response from Strategic Brain decomposing an objective."""

    planned_tasks: list[PlannedTask] = Field(
        ..., description="Decomposed research tasks"
    )
    strategic_rationale: str = Field(
        ..., description="Strategic reasoning for this decomposition"
    )


class StoppingEvaluation(BaseModel):
    """Epistemic evaluation of whether research stopping criteria have been satisfied."""

    should_stop: bool = Field(..., description="True if research loop should terminate")
    reason: str = Field(..., description="Justification for stopping or continuing")
    missing_fields: list[str] = Field(
        default_factory=list,
        description="Required fields not yet backed by supported claims",
    )
    coverage_score: float = Field(
        default=0.0,
        ge=0.0,
        le=1.0,
        description="Proportion of required fields satisfied",
    )
    field_statuses: dict[str, str] = Field(
        default_factory=dict,
        description="Epistemic status per required field (e.g. supported, inferred, not_found, unknown)",
    )


class DossierEntitySummary(BaseModel):
    """Entity dossier slice with verified claims, inferences, and flagged contradictions."""

    entity: Entity
    supported_claims: list[Claim] = Field(default_factory=list)
    corroborated_claims: list[Claim] = Field(default_factory=list)
    inferred_claims: list[Claim] = Field(default_factory=list)
    unverified_claims: list[Claim] = Field(default_factory=list)
    contradicted_claims: list[Claim] = Field(default_factory=list)


class SynthesisPayload(BaseModel):
    """Structured response for executive summary generation."""

    executive_summary: str = Field(
        ..., description="Comprehensive analytical synthesis of findings"
    )


class ResearchDossier(BaseModel):
    """The final immutable evidence-backed dossier generated by Argus."""

    objective_id: str
    target: str
    intelligence_goal: str
    executive_summary: str
    entities: list[DossierEntitySummary] = Field(default_factory=list)
    total_tasks_executed: int
    total_documents_crawled: int
    unresolved_contradictions: int
    coverage_achieved: float
    field_statuses: dict[str, str] = Field(
        default_factory=dict,
        description="Epistemic status per required field",
    )
